CREATE VIEW mart_recommendation_base AS WITH classification_agg AS (SELECT bgc.GameKey, string_agg(DISTINCT CASE  WHEN ((dc.ClassificationType = 'Genre')) THEN (dc.ClassificationValue) ELSE NULL END, ', ') AS Genres, string_agg(DISTINCT CASE  WHEN ((dc.ClassificationType = 'Theme')) THEN (dc.ClassificationValue) ELSE NULL END, ', ') AS Themes, string_agg(DISTINCT CASE  WHEN ((dc.ClassificationType = 'Mode')) THEN (dc.ClassificationValue) ELSE NULL END, ', ') AS Modes, string_agg(DISTINCT CASE  WHEN ((dc.ClassificationType = 'Perspective')) THEN (dc.ClassificationValue) ELSE NULL END, ', ') AS Perspectives FROM BridgeGameClassification AS bgc INNER JOIN DimClassification AS dc ON ((dc.ClassificationKey = bgc.ClassificationKey)) GROUP BY bgc.GameKey), play_activity AS (SELECT fpa.GameKey, dps.PlayStatusName, fpa.CompletionDateKey, fpa.LastPlayedDateKey FROM FactPlayActivity AS fpa INNER JOIN DimPlayStatus AS dps ON ((dps.PlayStatusKey = fpa.PlayStatusKey))), assessment AS (SELECT GameKey, DifficultyScore, BaseLengthHours, CompletionHours, PersonalRating, CuratedUserScore FROM FactUserGameAssessment)SELECT DISTINCT dg.GameKey, dg.GameID, dg.GameTitle, COALESCE(pa.PlayStatusName, 'Unknown') AS PlayStatusName, a.DifficultyScore, a.BaseLengthHours, a.CompletionHours, a.PersonalRating, a.CuratedUserScore, ca.Genres, ca.Themes, ca.Modes, ca.Perspectives FROM FactGameInventory AS fgi INNER JOIN DimGame AS dg ON ((dg.GameKey = fgi.GameKey)) LEFT JOIN play_activity AS pa ON ((pa.GameKey = dg.GameKey)) LEFT JOIN assessment AS a ON ((a.GameKey = dg.GameKey)) LEFT JOIN classification_agg AS ca ON ((ca.GameKey = dg.GameKey));
